from __future__ import annotations

import csv
import json
import re
from collections import defaultdict
from datetime import date, timedelta
from decimal import Decimal, ROUND_HALF_UP
from pathlib import Path

DATA_DIR = Path('/app/dataset')


def _read_csv(filename: str) -> list[dict[str, str]]:
    with (DATA_DIR / filename).open(newline='', encoding='utf-8-sig') as f:
        return list(csv.DictReader(f))


def _parse_date(value: str) -> date | None:
    """Parse a date, clamping impossible month-end days to that month's end."""
    match = re.fullmatch(r'(\d{4})-(\d{2})-(\d{2})', value.strip())
    if not match:
        return None
    year, month, day = map(int, match.groups())
    if not (1 <= month <= 12) or day < 1:
        return None
    try:
        return date(year, month, day)
    except ValueError:
        # The supplied invalid dates are April 31 and June 31. Treat these as
        # month-end entries, retaining their month for payroll grouping.
        next_month = date(year + (month == 12), month % 12 + 1, 1)
        return next_month - timedelta(days=1)


def _month_starts(first_day: date, last_day: date, weekday: int) -> list[date]:
    """First occurrence of weekday in each calendar month across the data."""
    starts: list[date] = []
    year, month = first_day.year, first_day.month
    while (year, month) <= (last_day.year, last_day.month):
        month_first = date(year, month, 1)
        offset = (weekday - month_first.weekday()) % 7
        starts.append(month_first + timedelta(days=offset))
        if month == 12:
            year, month = year + 1, 1
        else:
            month += 1
    return starts


def answer() -> dict[str, list[int]]:
    employees = _read_csv('employees.csv')
    tasks = _read_csv('tasks.csv')
    timesheet = _read_csv('timesheet.csv')

    rates = {row['PESEL']: Decimal(row['hourly_rate']) for row in employees}
    task_pay = {str(row['task_id']): Decimal(row['pay_per_completion']) for row in tasks}
    roster_ids = list(rates)

    # The invalid timesheet PESELs are single records for roster employees with
    # small, unique digit differences. Use a correction only when the nearest
    # roster PESEL is unique and within three digits.
    employee_id_map: dict[str, str] = {pesel: pesel for pesel in roster_ids}
    for row in timesheet:
        employee_id = row['employee_id'].strip()
        if employee_id in employee_id_map:
            continue
        distances = [
            (sum(a != b for a, b in zip(employee_id, pesel)), pesel)
            for pesel in roster_ids
            if len(pesel) == len(employee_id)
        ]
        if not distances:
            continue
        best_distance = min(distance for distance, _ in distances)
        best_matches = [pesel for distance, pesel in distances if distance == best_distance]
        if best_distance <= 3 and len(best_matches) == 1:
            employee_id_map[employee_id] = best_matches[0]

    parsed_rows: list[tuple[date, dict[str, str], str]] = []
    for row in timesheet:
        work_date = _parse_date(row.get('date', ''))
        pesel = employee_id_map.get(row.get('employee_id', '').strip())
        if work_date is None or pesel is None:
            continue
        parsed_rows.append((work_date, row, pesel))

    if not parsed_rows:
        return {pesel: [] for pesel in roster_ids}

    earliest = min(work_date for work_date, _, _ in parsed_rows)
    latest = max(work_date for work_date, _, _ in parsed_rows)
    # The first dated timesheet entry establishes the weekday for the recurring
    # start of each billing month.
    weekday = earliest.weekday()
    starts = _month_starts(earliest, latest, weekday)
    month_labels = [start.strftime('%Y-%m') for start in starts]
    monthly_total: dict[str, dict[str, Decimal]] = {
        pesel: {label: Decimal(0) for label in month_labels}
        for pesel in roster_ids
    }

    for work_date, row, pesel in parsed_rows:
        # A record belongs to the most recent billing-month start on or before
        # its date. Dates before a month's first weekday remain in the prior cycle.
        applicable = [i for i, start in enumerate(starts) if start <= work_date]
        if not applicable:
            continue
        month_label = month_labels[applicable[-1]]

        try:
            hours = Decimal(row['hours_worked'])
        except Exception:
            continue
        if hours < 0:
            continue

        # Extract task IDs even when list brackets or separators are damaged.
        completed_ids = re.findall(r'\d+', row.get('performed_tasks', ''))
        bonus = sum((task_pay[task_id] for task_id in completed_ids if task_id in task_pay), Decimal(0))
        monthly_total[pesel][month_label] += hours * rates[pesel] + bonus

    return {
        pesel: [
            int(monthly_total[pesel][label].quantize(Decimal('1'), rounding=ROUND_HALF_UP))
            for label in month_labels
        ]
        for pesel in roster_ids
    }


if __name__ == '__main__':
    with open('/app/answer.json', 'w', encoding='utf-8') as f:
        json.dump(answer(), f, ensure_ascii=False)
